import{_ as a,o as s,c as t,ae as n}from"./chunks/framework.1HOg4yJX.js";const u=JSON.parse('{"title":"Monad — Subtractive Synthesis","description":"","frontmatter":{"layout":"doc","title":"Monad — Subtractive Synthesis"},"headers":[],"relativePath":"Subtractive-Synthesis.md","filePath":"Subtractive-Synthesis.md"}'),o={name:"Subtractive-Synthesis.md"};function i(r,e,l,h,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="monad-subtractive-synthesis" tabindex="-1">Monad: Subtractive Synthesis <a class="header-anchor" href="#monad-subtractive-synthesis" aria-label="Permalink to &quot;Monad: Subtractive Synthesis&quot;">​</a></h1><p>In audio synthesis, <strong>subtractive synthesis</strong> starts with a rich source signal and removes what you don&#39;t need — the output is defined by what remains after filtering, not by building up from scratch.</p><p>Monad routing works the same way.</p><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><p>A namespace like <code>suis-macbook-air.local</code> is not a single process. It is a <strong>surface</strong> — potentially many monad Express instances running at different ports, each handling a slice of the workload:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>suis-macbook-air.local</span></span>
<span class="line"><span>  monad:cleaker   → port 4101  (healthy)</span></span>
<span class="line"><span>  monad:netget    → port 4102  (healthy)</span></span>
<span class="line"><span>  monad:cold-store           (sleeping)</span></span></code></pre></div><p>Netget does not know which monad to route to in advance. Instead, it holds all registered entries for that namespace and <strong>subtracts</strong> the ones that are unfit:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>all registered monads for namespace</span></span>
<span class="line"><span>  − expired entries (TTL elapsed, heartbeat stopped)</span></span>
<span class="line"><span>  − unhealthy entries (health check failing)</span></span>
<span class="line"><span>  ─────────────────────────────────────────────</span></span>
<span class="line"><span>  → route to the highest-scored remaining monad</span></span></code></pre></div><p>The scoring (<code>meshSelect.ts</code>) weighs <code>lastSeenMs</code>, health state, and capability flags. The winner gets the proxied request.</p><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><ul><li><strong>The namespace is stable</strong> even as individual monads restart, crash, or scale.</li><li><strong>No central coordinator</strong> decides what&#39;s alive — each monad declares itself alive by sending heartbeats. Silence means absence.</li><li><strong>New monads join</strong> by registering. Old ones leave by going silent. The surface reshapes itself continuously.</li></ul><p>This is the opposite of additive: you don&#39;t build the namespace by enumerating every piece. You start with everything that has announced itself and cut away what&#39;s gone.</p><h2 id="relation-to-the-monad-bubble" tabindex="-1">Relation to the Monad bubble <a class="header-anchor" href="#relation-to-the-monad-bubble" aria-label="Permalink to &quot;Relation to the Monad bubble&quot;">​</a></h2><p>The <code>Monad</code> component&#39;s <code>healthy</code> prop reflects the synthesized output of this process — it is <code>true</code> when at least one monad in the mesh remains after filtering, <code>false</code> when all have been subtracted away, and <code>null</code> when no entries have ever arrived.</p><p>The orb does not represent one process. It represents whether the <strong>surface</strong> is alive.</p>`,15)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
